// Account What the key may do.
type Account struct {
	// Api The state of the API for this seller.
	Api AccountApi `json:"api"`

	// Key This key.
	Key AccountKey `json:"key"`

	// Limits The limits that apply to this key.
	Limits AccountLimits `json:"limits"`

	// Marketplaces The marketplaces whose orders the seller sends through this API. An order names one of these codes.
	Marketplaces []AccountMarketplace `json:"marketplaces"`

	// Seller The seller this key belongs to.
	Seller AccountSeller `json:"seller"`

	// ServerTime The fulfilment centre's clock, to compare with the caller's.
	ServerTime time.Time `json:"server_time"`
}

// AccountApi The state of the API for this seller.
type AccountApi struct {
	// Enabled False when the seller switched the API off: every call is refused until it is switched on.
	Enabled bool `json:"enabled"`
}

// AccountKeyAccess `read_only` keys are refused on every write with `read_only_key`.
type AccountKeyAccess string

// AccountKey This key.
type AccountKey struct {
	// Access `read_only` keys are refused on every write with `read_only_key`.
	Access AccountKeyAccess `json:"access"`

	// Name The name given to the key when it was created.
	Name string `json:"name"`
}

// AccountLimits The limits that apply to this key.
type AccountLimits struct {
	// BodyBytes The largest JSON body.
	BodyBytes int `json:"body_bytes"`

	// FileBodyBytes The largest body of a call that carries a file.
	FileBodyBytes int `json:"file_body_bytes"`

	// MaxPageSize The largest `limit`.
	MaxPageSize int `json:"max_page_size"`

	// PageSize The page size when `limit` is absent.
	PageSize int `json:"page_size"`

	// RequestsPerMinute Requests a minute per key.
	RequestsPerMinute int `json:"requests_per_minute"`

	// RetentionDays How long events, the journal and deliveries are kept.
	RetentionDays int `json:"retention_days"`
}

// AccountMarketplace defines model for Account.marketplaces.
type AccountMarketplace struct {
	// Code The marketplace's code, as an order's `marketplace` takes it.
	Code string `json:"code"`

	// Name The marketplace's name for a person to read.
	Name string `json:"name"`
}

// AccountSeller The seller this key belongs to.
type AccountSeller struct {
	// Name The seller's name.
	Name string `json:"name"`
}

// CourierCodeAnswerIn The answer to the code a courier named for an order that leaves alone (`order.courier_code_entered`). The same answer may be sent again; a different answer to an answered check is refused with `conflict`.
type CourierCodeAnswerIn struct {
	// AttemptsLeft How many tries of the code the marketplace still allows, when it says.
	AttemptsLeft *int `json:"attempts_left,omitempty"`

	// Message The marketplace's own words, shown to the warehouse's worker.
	Message *string `json:"message,omitempty"`

	// Result `accepted`: the marketplace accepted the code, and the parcels are given to the courier; `refused`: the code is wrong; `new_code_needed`: the marketplace sends the courier a new code.
	Result CourierCodeAnswerInResult `json:"result"`
}

// CourierCodeAnswerInResult `accepted`: the marketplace accepted the code, and the parcels are given to the courier; `refused`: the code is wrong; `new_code_needed`: the marketplace sends the courier a new code.
