// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Account Read what the key allows
	// (GET /account)
	Account(w http.ResponseWriter, r *http.Request)
	// EventList Read the events
	// (GET /events)
	EventList(w http.ResponseWriter, r *http.Request, params EventListParams)
	// HandoverList List the hand-overs
	// (GET /handovers)
	HandoverList(w http.ResponseWriter, r *http.Request, params HandoverListParams)
	// HandoverGet Read one hand-over
	// (GET /handovers/{id})
	HandoverGet(w http.ResponseWriter, r *http.Request, id string)
	// HandoverDocuments Send the hand-over's documents
	// (PUT /handovers/{id}/documents)
	HandoverDocuments(w http.ResponseWriter, r *http.Request, id string)
	// HandoverProblemClear Clear a hand-over's problem
	// (DELETE /handovers/{id}/problem)
	HandoverProblemClear(w http.ResponseWriter, r *http.Request, id string)
	// HandoverProblemSet Report a problem with a hand-over
	// (PUT /handovers/{id}/problem)
	HandoverProblemSet(w http.ResponseWriter, r *http.Request, id string)
	// HeldList List the orders that wait
	// (GET /held-orders)
	HeldList(w http.ResponseWriter, r *http.Request)
	// HeldWithdraw Withdraw an order that waits
	// (DELETE /held-orders/{id})
	HeldWithdraw(w http.ResponseWriter, r *http.Request, id string)
	// HeldGet Read a received order
	// (GET /held-orders/{id})
	HeldGet(w http.ResponseWriter, r *http.Request, id string)
	// OrderList List the orders
	// (GET /orders)
	OrderList(w http.ResponseWriter, r *http.Request, params OrderListParams)
	// OrderCreate Send an order
	// (POST /orders)
	OrderCreate(w http.ResponseWriter, r *http.Request)
	// OrderGet Read one order
	// (GET /orders/{id})
	OrderGet(w http.ResponseWriter, r *http.Request, id string)
	// OrderPatch Change the deadline and the note
	// (PATCH /orders/{id})
	OrderPatch(w http.ResponseWriter, r *http.Request, id string)
	// OrderCancel Cancel an order
	// (POST /orders/{id}/cancel)
	OrderCancel(w http.ResponseWriter, r *http.Request, id string)
	// CourierCodeAnswer Answer a courier's code
	// (PUT /orders/{id}/courier-code-checks/{check_id})
	CourierCodeAnswer(w http.ResponseWriter, r *http.Request, id string, checkId string)
	// LabelDelete Remove a parcel's label
	// (DELETE /orders/{id}/parcels/{number}/label)
	LabelDelete(w http.ResponseWriter, r *http.Request, id string, number int)
	// LabelPut Attach a label to a parcel
	// (PUT /orders/{id}/parcels/{number}/label)
	LabelPut(w http.ResponseWriter, r *http.Request, id string, number int)
	// OrderProblemClear Clear an order's problem
	// (DELETE /orders/{id}/problem)
	OrderProblemClear(w http.ResponseWriter, r *http.Request, id string)
	// OrderProblemSet Report a problem with an order
	// (PUT /orders/{id}/problem)
	OrderProblemSet(w http.ResponseWriter, r *http.Request, id string)
	// OrderReduce Reduce an order
	// (POST /orders/{id}/reduce)
	OrderReduce(w http.ResponseWriter, r *http.Request, id string)
	// Warehouses List the warehouses
	// (GET /warehouses)
	Warehouses(w http.ResponseWriter, r *http.Request)
}

