// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account", wrapper.Account)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/warehouses", wrapper.Warehouses)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/orders", wrapper.OrderList)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/orders", wrapper.OrderCreate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/orders/{id}", wrapper.OrderGet)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/orders/{id}", wrapper.OrderPatch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/orders/{id}/cancel", wrapper.OrderCancel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/orders/{id}/reduce", wrapper.OrderReduce)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/orders/{id}/problem", wrapper.OrderProblemClear)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/orders/{id}/problem", wrapper.OrderProblemSet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/orders/{id}/courier-code-checks/{check_id}", wrapper.CourierCodeAnswer)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/orders/{id}/parcels/{number}/label", wrapper.LabelDelete)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/orders/{id}/parcels/{number}/label", wrapper.LabelPut)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/held-orders", wrapper.HeldList)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/held-orders/{id}", wrapper.HeldWithdraw)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/held-orders/{id}", wrapper.HeldGet)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.EventList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/handovers", wrapper.HandoverList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/handovers/{id}", wrapper.HandoverGet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/handovers/{id}/documents", wrapper.HandoverDocuments)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/handovers/{id}/problem", wrapper.HandoverProblemClear)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/handovers/{id}/problem", wrapper.HandoverProblemSet)

	return m
}

// WebhookReceiverInterface represents handlers for receiving inbound
// webhook requests. Each webhook becomes a Handle*Webhook
// method that the implementation fills in. The caller mounts the per-
// webhook http.Handler returned by {Op}WebhookHandler at
// whatever URL path they advertise to senders.
type WebhookReceiverInterface interface {
	// Every parcel of the hand-over left.
	// HandleWebhookHandoverCompletedWebhook handles the POST webhook for handover.completed.
	HandleWebhookHandoverCompletedWebhook(w http.ResponseWriter, r *http.Request, params WebhookHandoverCompletedParams)
	// The fulfilment centre withdrew its request for the documents.
	// HandleWebhookHandoverRequestWithdrawnWebhook handles the POST webhook for handover.request_withdrawn.
	HandleWebhookHandoverRequestWithdrawnWebhook(w http.ResponseWriter, r *http.Request, params WebhookHandoverRequestWithdrawnParams)
	// The fulfilment centre asks for the hand-over's documents: the sender closes its supply and sends them. From now on the hand-over takes no more parcels.
	// HandleWebhookHandoverRequestedWebhook handles the POST webhook for handover.requested.
	HandleWebhookHandoverRequestedWebhook(w http.ResponseWriter, r *http.Request, params WebhookHandoverRequestedParams)
	// A working order exists: made at once or taken from the waiting list.
	// HandleWebhookOrderAcceptedWebhook handles the POST webhook for order.accepted.
	HandleWebhookOrderAcceptedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderAcceptedParams)
	// The order is cancelled; `details.by` is `outside_system` or `warehouse`.
	// HandleWebhookOrderCancelledWebhook handles the POST webhook for order.cancelled.
	HandleWebhookOrderCancelledWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderCancelledParams)
	// A cancel or a cut waits for a person at the fulfilment centre (`details.field`, `details.why`).
	// HandleWebhookOrderChangeWaitsWebhook handles the POST webhook for order.change_waits.
	HandleWebhookOrderChangeWaitsWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderChangeWaitsParams)
	// A courier named a code for an order that leaves alone; `details.check_id` and `details.code` (null once the code is erased). Answer with `PUT /orders/{id}/courier-code-checks/{check_id}`.
	// HandleWebhookOrderCourierCodeEnteredWebhook handles the POST webhook for order.courier_code_entered.
	HandleWebhookOrderCourierCodeEnteredWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderCourierCodeEnteredParams)
	// The last parcel left with the carrier.
	// HandleWebhookOrderHandedOverWebhook handles the POST webhook for order.handed_over.
	HandleWebhookOrderHandedOverWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderHandedOverParams)
	// The order was received and waits.
	// HandleWebhookOrderHeldWebhook handles the POST webhook for order.held.
	HandleWebhookOrderHeldWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderHeldParams)
	// A label was attached to a parcel (`details.parcel`).
	// HandleWebhookOrderLabelAttachedWebhook handles the POST webhook for order.label_attached.
	HandleWebhookOrderLabelAttachedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderLabelAttachedParams)
	// The last parcel was closed: the whole order is packed.
	// HandleWebhookOrderPackedWebhook handles the POST webhook for order.packed.
	HandleWebhookOrderPackedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderPackedParams)
	// Packing is finished: the contents of the parcels and every unit's marking code are final. This is the event that carries the codes.
	// HandleWebhookOrderPackingFinishedWebhook handles the POST webhook for order.packing_finished.
	HandleWebhookOrderPackingFinishedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderPackingFinishedParams)
	// A parcel was closed (`details.parcel`).
	// HandleWebhookOrderParcelClosedWebhook handles the POST webhook for order.parcel_closed.
	HandleWebhookOrderParcelClosedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderParcelClosedParams)
	// The order is picked and waits for packing.
	// HandleWebhookOrderPickedWebhook handles the POST webhook for order.picked.
	HandleWebhookOrderPickedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderPickedParams)
	// The order was released to picking.
	// HandleWebhookOrderPickingStartedWebhook handles the POST webhook for order.picking_started.
	HandleWebhookOrderPickingStartedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderPickingStartedParams)
	// Lines of the order were cut.
	// HandleWebhookOrderReducedWebhook handles the POST webhook for order.reduced.
	HandleWebhookOrderReducedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderReducedParams)
	// A parcel was reopened or packing was restarted: the marking codes sent before no longer hold.
	// HandleWebhookOrderReopenedWebhook handles the POST webhook for order.reopened.
	HandleWebhookOrderReopenedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderReopenedParams)
	// The order's goods are set aside.
	// HandleWebhookOrderReservedWebhook handles the POST webhook for order.reserved.
	HandleWebhookOrderReservedWebhook(w http.ResponseWriter, r *http.Request, params WebhookOrderReservedParams)
	// A test notification, sent on request, to check the address and the signature.
	// HandleWebhookPingWebhook handles the POST webhook for ping.
	HandleWebhookPingWebhook(w http.ResponseWriter, r *http.Request, params WebhookPingParams)
}

// WebhookReceiverMiddlewareFunc wraps an http.Handler with cross-
// cutting behavior (signature verification, logging, rate limiting, ...).
